var t=`0869-sindhi-biryani`;var n=`world-0869`;var a=`PK`;var r=`south-asia`;var s=4;var o=143;var g={en:`Sindhi Biryani`,ua:`Сіндський бір'яні`};var l={en:`Sindhi Biryani is a Pakistan dish made with chicken thigh, plain yogurt, ginger-garlic paste, yellow onion. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сіндський бір'яні, страва кухні країни Пакистан. Основні складники: куряче стегно, натуральний йогурт, імбирно-часникова паста, жовта цибуля. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 60 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 60 хвилин.`,t:[`marinating`],m:60,i:[[`chicken-thigh`,730,`g`],[`plain-yogurt`,150,`g`],[`ginger-garlic-paste`,25,`g`],[`garam-masala`,8,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,230,`g`],[`tomato`,270,`g`],[`ghee`,60,`g`],[`serrano-pepper`,3,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`basmati-rice`,430,`g`],[`water`,1e3,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`potato`,250,`g`],[`mint`,18,`g`],[`cilantro`,20,`g`],[`prune`,75,`g`]]},{en:`Put the prepared parcels in a steamer over gently boiling water, cover, and steam for about 38 minutes until the filling is completely cooked.`,ua:`Покладіть підготовлені вироби на решітку пароварки над водою, що ледь кипить, накрийте й готуйте на парі приблизно 38 хвилин до повної готовності начинки.`,t:[`steaming`],m:38,i:[]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 12 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 12 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:12,i:[]}];var u={slug:t,id:n,country:`PK`,region:r,servings:4,minutes:143,title:g,text:l,steps:h};export{a as country,u as default,n as id,o as minutes,r as region,s as servings,t as slug,h as steps,l as text,g as title};